"""Volume 2 · Module 13 « Contes du monde » (A2)."""
import sys
sys.path.insert(0, '/home/claude/syllabus')
from lib.base import *
from lib.art import *
from lib.module import *
from lib.v2 import CP, CPCOL
from lib.render import to_pdf

MC = "#B5462F"
TINT = "#FBEDE7"
PERS = [("👑", "un roi · une reine"), ("🤴", "un prince · une princesse"), ("🧙", "un sorcier · une sorcière"), ("🧚", "une fée"), ("🐉", "un dragon"), ("👹", "un ogre · une ogresse"),
        ("🐢", "une vieille tortue"), ("🦊", "un renard rusé"), ("🐇", "un lièvre malin"), ("🧑‍🌾", "un paysan · une paysanne"), ("🧒", "un orphelin · une orpheline"), ("🐺", "un loup")]
OBJ = [("🪄", "une baguette magique"), ("🥁", "un tambour"), ("💍", "un anneau"), ("🗝️", "une clé d'or"), ("🪞", "un miroir magique"), ("🍎", "une pomme empoisonnée"), ("👢", "des bottes de sept lieues"), ("🧺", "un panier")]


def build_v2m13(start=1, tstart=1, render=True):
    b = Book("V2 · M13", "Volume 2 · Je me débrouille · Module 13 · Contes du monde", MC, start=start)
    E = Ex(b)
    vis = ('<div class="flex" style="justify-content:space-around;align-items:flex-end">' + avatar("fatou", 80, "rire") + '<div style="font-size:34pt">🐇🌳</div>' + avatar("daria", 80, "sourire") + '<div style="font-size:34pt">🧤🐻</div>'
           + avatar("yonas", 80, "pense") + '<div style="font-size:34pt">🐉🏰</div>' + avatar("prof", 80, "sourire") + '</div>')
    opening(b, MC, 13, "Contes du monde", vis, [("📖", "lire et comprendre un conte"), ("🧙", "nommer les personnages, les lieux et les objets magiques"), ("⏳", "raconter au passé : imparfait et passé composé"),
            ("🔗", "enchaîner les actions : un jour, soudain, alors, finalement…"), ("🗺️", "trouver le schéma narratif d'une histoire"), ("🎙️", "raconter un conte de mon pays")],
            ["Connais-tu un conte de ton pays ? Qui te l'a raconté ?", "Quels personnages trouve-t-on souvent dans les contes ?", "Dans ta langue, comment commence un conte ?"],
            ["un conte", "il était une fois", "un personnage", "un héros", "magique", "un jour", "soudain", "finalement", "la morale", "raconter"], TINT)

    # ---------- Découvrir ----------
    bd = '<div class="grid2" style="gap:3mm">' + "".join([
        bd_case(1, lr("prof", ["La semaine prochaine, la bibliothèque organise « Contes du monde ». Chacun pourra raconter un conte de son pays !"], "fatou", ["Super ! Ma grand-mère me racontait toujours l'histoire de Leuk le lièvre."], "sourire", "rire")),
        bd_case(2, lr("daria", ["Chez nous, en Ukraine, il y a le conte de la moufle : des animaux entrent un par un dans un gant perdu dans la neige."], "mateo", ["Dans un gant ? Ils étaient tout petits ?"], "sourire", "surpris")),
        bd_case(3, lr("daria", ["Non ! Il y avait même un ours ! C'est ça, la magie des contes."], "bilal", ["Moi, je ne connais pas bien les contes. Je ne sais pas comment raconter."], "rire", "pense")),
        bd_case(4, lr("educ", ["C'est facile, Bilal : on commence par « Il était une fois… ». Ensuite, il y a un problème. Le héros vit des aventures…"], "bilal", ["… et à la fin, tout s'arrange ?"], "sourire", "pense")),
        bd_case(5, lr("prof", ["Souvent, oui ! Et parfois, il y a une morale : une leçon pour la vie."], "yonas", ["Chez nous, en Érythrée, on dit qu'un conte se raconte le soir, jamais le matin !"], "sourire", "pense")),
        bd_case(6, lr("amina", ["Alors on organisera la soirée des contes le soir ! Avec du thé et des biscuits !"], "prof", ["Excellente idée, Amina ! Au travail, conteurs et conteuses !"], "rire", "rire")),
    ]) + '</div>'
    e = E("J'écoute et je lis la BD : la soirée des contes.", bd, ["ecoute", "lis"], 1, "A",
          script="Lire deux fois, avec une voix de conteur. Demander : « Qu'est-ce que la bibliothèque organise ? Quel conte connaît Fatou ? Daria ? Pourquoi Bilal est-il inquiet ? Comment commence un conte ? Qu'est-ce qu'une morale ? Que propose Amina ? »", sol="Activité orale.")
    b.page(f'<h2>Découvrir · La soirée des contes</h2>{e}', "Découvrir")
    e = E("Je réponds par une phrase complète.", f'<p>1. Qu\'est-ce que la bibliothèque organise ? {blank("xl")}</p><p>2. Qui racontait des histoires à Fatou ? {blank("xl")}</p><p>3. Que se passe-t-il dans le conte de la moufle ? {blank("xl")}</p><p>4. Comment commence souvent un conte ? {blank("xl")}</p><p>5. Qu\'est-ce qu\'une morale ? {blank("xl")}</p><p>6. Quand raconte-t-on les contes dans le pays de Yonas ? {blank("xl")}</p>', ["lis", "ecris"], 1, "B",
          sol="1. Une activité « Contes du monde » : chacun pourra raconter un conte de son pays. — 2. Sa grand-mère. — 3. Des animaux entrent un par un dans un gant perdu dans la neige (même un ours !). — 4. Par « Il était une fois… ». — 5. Une leçon pour la vie. — 6. Le soir, jamais le matin.")
    e2 = E("Vrai ou faux ? Je coche.", vf(["Bilal connaît beaucoup de contes.", "Dans le conte de la moufle, il y a un ours.", "Dans un conte, il y a souvent un problème.", "La soirée des contes aura lieu le matin."]), ["lis", "coche"], 1, "B",
           sol="Faux · Vrai · Vrai · Faux (le soir)")
    e3 = E("Et toi ? Qui te racontait des histoires quand tu étais petit(e) ? Lesquelles ? (2 phrases)", lines(2), ["ecris"], 2, "C", sol="Ex. : Mon grand-père me racontait des histoires d'animaux. Je préférais l'histoire du singe et du crocodile.")
    e4 = E("Les mots de la BD. Je trouve le mot qui veut dire…", '<p>1. une histoire imaginaire, souvent avec de la magie : un ______________ 2. le personnage principal : le ______________ 3. une leçon pour la vie : la ______________ 4. une personne qui raconte des contes : un ______________ / une ______________</p>', ["lis", "ecris"], 1, "B",
           sol="1. conte — 2. héros (l'héroïne) — 3. morale — 4. conteur / conteuse")
    b.page(f'{e}{e2}{e3}{e4}', "Découvrir")
    aff = f'''<div class="doc" style="transform:none;border:2px solid {MC};background:#FFFDF8;padding:3mm 4mm"><div class="flex" style="justify-content:space-between"><div><b style="font-size:15pt;color:{MC}">📚 Bibliothèque communale de Meuse-sur-Sambre</b><br><span class="xs muted">(bibliothèque fictive)</span></div><div style="font-size:30pt">🌍📖</div></div>
<div style="text-align:center;font-size:20pt;font-weight:800;color:{MC};margin:2mm 0">« Contes du monde »</div>
<p style="text-align:center;margin:0">Une soirée pour voyager avec des histoires de tous les pays</p>
{table(["Quand ?", "Quoi ?", "Pour qui ?"], [["vendredi 11 décembre · 18 h 30", "Ouverture : contes d'Afrique de l'Ouest avec la conteuse Awa (accompagnée au djembé)", "dès 6 ans"], ["19 h 15", "Scène ouverte : les élèves de la classe DASPA racontent un conte de leur pays (5 minutes chacun)", "tout public"], ["20 h", "Tisane, thé à la menthe et biscuits du monde (apportez une spécialité si vous le souhaitez)", "tout public"], ["samedi 12 décembre · 10 h", "Atelier « Fabrique ton livre de contes » (inscription obligatoire, 12 places)", "de 10 à 14 ans"]], ["46mm", "100mm", "36mm"])}
<p class="xs" style="margin:1mm 0 0">🎟️ Entrée libre (atelier du samedi : 2 €). · 📞 Inscriptions : 081 00 00 00 (numéro fictif) ou au comptoir. · ♿ Salle accessible. · Les contes sont racontés en français ; certains passages dans la langue d'origine.</p></div>'''
    e = E("Je lis l'affiche de la bibliothèque. Je réponds.", aff + f'<p class="mt2">1. Quand a lieu la soirée ? À quelle heure commence-t-elle ? {blank("xl")}</p><p>2. Qui est Awa ? Quel instrument accompagne ses contes ? {blank("xl")}</p><p>3. Combien de temps a chaque élève pour raconter ? {blank("l")} 4. Combien coûte l\'atelier ? {blank("s")}</p><p>5. Bilal a 15 ans. Peut-il participer à l\'atelier du samedi ? Pourquoi ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Le vendredi 11 décembre, à 18 h 30. — 2. Une conteuse (contes d'Afrique de l'Ouest) ; le djembé. — 3. Cinq minutes. — 4. 2 €. — 5. Non : l'atelier est pour les jeunes de 10 à 14 ans.")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Découvrir · L\'affiche de la bibliothèque</h2>{e}', "Découvrir")

    # ---------- Lexique ----------
    e = E("Les personnages des contes. J'écoute et je répète.", emogrid(PERS, 6, False).replace('font-size:10pt', 'font-size:9pt'), ["ecoute", "repete"], 1, "A",
          script="Lire chaque personnage au masculin puis au féminin. Faire remarquer : sorcier → sorcière, ogre → ogresse, paysan → paysanne, prince → princesse. « Rusé, malin » = intelligent pour tromper les autres.", sol="Activité orale.")
    e2 = E("Les objets magiques. Je relie l'objet et son pouvoir.", '<div class="grid4" style="margin-bottom:2mm">' + "".join(f'<div class="card c" style="padding:1.5mm"><span style="font-size:18pt">{a}</span><br><span class="xs">{t}</span></div>' for a, t in OBJ) + '</div>' +
           relie(["la baguette magique", "les bottes de sept lieues", "le miroir magique", "la clé d'or", "la pomme empoisonnée"], ["fait dormir pour toujours", "ouvre la porte secrète", "transforme une citrouille en carrosse", "permet de marcher très, très vite", "répond à toutes les questions"]), ["relie"], 1, "B",
           sol="baguette → transforme une citrouille en carrosse · bottes → marcher très vite · miroir → répond aux questions · clé d'or → porte secrète · pomme → fait dormir pour toujours")
    b.page(f'<h2>Les personnages et les objets magiques</h2>{e}{e2}', "Lexique")
    l0 = lecon("Les lieux et les formules du conte", '''<div class="grid2"><div class="card" style="background:#fff"><b>🏰 Les lieux</b><p class="sm" style="margin:1mm 0 0">un château · une forêt profonde · une grotte · un village · une cabane · un puits · un désert · une montagne · le palais du roi · le fond de la mer · un royaume lointain</p></div>
<div class="card" style="background:#fff"><b>✨ Les formules</b><p class="sm" style="margin:1mm 0 0"><b>Pour commencer :</b> Il était une fois… · Il y a très longtemps, dans un pays lointain… · Autrefois, vivait…<br><b>Pour finir :</b> Ils vécurent heureux… · Et depuis ce jour… · C'est ainsi que… · Et mon conte est fini !</p></div></div>
<div class="astuce" style="margin:2mm 0 0">🌍 Chaque langue a ses formules. En créole haïtien, le conteur dit « Krik ? » et le public répond « Krak ! ». Dans ma langue, un conte commence par : ……………………………… </div>''')
    e = E("Où se passe l'histoire ? J'écris le lieu.", '<p>1. Le dragon dort dans une ______________ au pied de la montagne. 2. La princesse habite dans un ______________ avec des tours. 3. Le petit chaperon traverse une ______________ pleine de loups. 4. La grenouille vit au fond d\'un ______________ . 5. Le pêcheur habite une petite ______________ au bord de la mer.</p>', ["complete"], 1, "C",
          sol="1. grotte — 2. château — 3. forêt — 4. puits — 5. cabane")
    e2 = E("Début ou fin ? Je classe les formules.", '<p class="sm">Il était une fois · Et depuis ce jour… · Autrefois vivait… · C\'est ainsi que… · Il y a très longtemps… · Et mon conte est fini !</p>' + table(["🚪 Début du conte", "🏁 Fin du conte"], [["", ""]], ["91mm", "91mm"]).replace("<td></td>", '<td style="height:16mm"></td>'), ["lis", "ecris"], 1, "C",
           sol="Début : Il était une fois · Autrefois vivait… · Il y a très longtemps… — Fin : Et depuis ce jour… · C'est ainsi que… · Et mon conte est fini !")
    e3 = E("Les formules dans nos langues. J'écris comment on commence et comment on finit un conte dans ma langue, puis je traduis en français.", table(["Ma langue", "Pour commencer…", "Pour finir…"], [["", "", ""], ["", "", ""]], ["40mm", "71mm", "71mm"]).replace("<td></td>", '<td style="height:12mm"></td>'), ["ecris"], 2, "C",
           sol="Réponses personnelles ; mettre en commun et afficher les formules des langues de la classe.")
    b.page(f'{l0}{e}{e2}{e3}', "Lexique")
    e = E("Les qualités et les défauts des personnages. Je classe les adjectifs.", '<p class="sm">courageux · méchant · rusé · généreux · jaloux · gourmand · sage · paresseux · cruel · gentil · orgueilleux · malin</p>' + table(["😊 qualités", "😠 défauts", "🤔 les deux (ça dépend)"], [["", "", ""]], ["61mm", "61mm", "60mm"]).replace("<td></td>", '<td style="height:18mm"></td>'), ["lis", "ecris"], 1, "C",
          sol="Qualités : courageux, généreux, sage, gentil — Défauts : méchant, jaloux, paresseux, cruel, orgueilleux, gourmand — Les deux : rusé, malin (intelligents, mais parfois pour tromper)")
    e2 = E("Je complète avec le contraire : généreux · courageux · sage · travailleur.", '<div class="card" style="line-height:2">1. Le lièvre est paresseux, la fourmi est ______________ . 2. L\'ogre est avare, la fée est ______________ . 3. Le prince a peur, la princesse est ______________ . 4. Le jeune roi est fou, le vieux conseiller est ______________ .</div>', ["complete"], 1, "C",
           sol="1. travailleuse — 2. généreuse — 3. courageuse — 4. sage")
    bel = table(["En Belgique, on dit…", "En France, on dit…", "Exemple"], [["une <b>drache</b>", "une grosse averse", "Une drache est tombée sur le village."], ["il fait <b>cru</b>", "il fait froid et humide", "Il faisait cru dans la forêt."], ["la <b>ducasse</b>", "la fête du village (foire)", "Les géants dansent à la ducasse."], ["<b>savoir</b> (= pouvoir)", "pouvoir", "Le loup ne sait pas entrer. (= ne peut pas)"]], ["48mm", "56mm", "78mm"])
    e3 = E("🇧🇪 Les mots d'ici. Je lis et je réécris la phrase en français de France.", bel + '<p class="mt2">Il faisait cru et une drache tombait : le petit lièvre ne savait pas rentrer chez lui. → ______________________________________________________</p>', ["lis", "ecris"], 2, "B",
           sol="Il faisait froid et humide et une grosse averse tombait : le petit lièvre ne pouvait pas rentrer chez lui.")
    e4 = E("Qui est-ce ? Je trouve un personnage de conte pour chaque adjectif (un conte que je connais).", '<div class="grid2" style="gap:1mm 6mm"><p>rusé : ______________</p><p>méchant : ______________</p><p>courageux : ______________</p><p>généreux : ______________</p></div>', ["ecris"], 2, "C",
           sol="Ex. : rusé → le renard, Leuk le lièvre · méchant → le loup, la sorcière · courageux → Nala, le petit tailleur · généreux → la fée.")
    b.page(f'<h2>Décrire les personnages · les mots d\'ici</h2>{e}{e2}{e3}{e4}', "Lexique")

    # ---------- Lecture : le conte ----------
    conte = f'''<div class="doc" style="transform:none;border:2px solid {MC};background:#FFFDF8;padding:4mm 6mm;font-size:11pt;line-height:1.6">
<div class="flex" style="justify-content:space-between"><b style="font-size:16pt;color:{MC}">🥁 Le tambour de la pluie</b><span class="xs muted">conte original écrit pour ce livre</span></div>
<p style="margin:2mm 0 0"><b>①</b> Il était une fois, au bord d'un grand désert, un petit village où vivait une orpheline, Nala. Elle était pauvre, mais elle était généreuse et elle partageait toujours son eau avec les animaux.</p>
<p style="margin:1.5mm 0 0"><b>②</b> Une année, la pluie n'est pas venue. Les puits étaient vides, les champs étaient jaunes et les enfants avaient soif. Le chef du village a dit : « Si personne ne trouve d'eau, nous devrons partir. »</p>
<p style="margin:1.5mm 0 0"><b>③</b> Un matin, Nala a trouvé une vieille tortue sur le chemin. La pauvre bête ne bougeait plus. Nala lui a donné ses dernières gouttes d'eau. Alors, la tortue a ouvert les yeux et elle a parlé : « Tu as un bon cœur. Va jusqu'à la montagne rouge. Là-bas, dans une grotte, tu trouveras le tambour de la pluie. »</p>
<p style="margin:1.5mm 0 0"><b>④</b> Nala est partie le soir même. Elle a marché pendant trois jours. D'abord, elle a traversé le désert brûlant. Ensuite, elle a rencontré une hyène affamée : elle lui a donné son pain et la hyène l'a laissée passer. Enfin, elle est arrivée devant la grotte, mais un serpent géant gardait l'entrée. Nala tremblait. Soudain, elle s'est souvenue des paroles de sa grand-mère : « La douceur ouvre toutes les portes. » Elle a chanté une berceuse. Le serpent s'est endormi.</p>
<p style="margin:1.5mm 0 0"><b>⑤</b> Au fond de la grotte, Nala a trouvé un petit tambour. Elle l'a rapporté au village et elle a frappé trois coups. Aussitôt, le ciel est devenu noir et une pluie énorme est tombée.</p>
<p style="margin:1.5mm 0 0"><b>⑥</b> Depuis ce jour, les puits ne sont plus jamais vides. Et quand le tonnerre gronde, les gens du village disent : « Écoutez, c'est Nala qui joue du tambour ! »</p></div>'''
    e = E("J'écoute et je lis le conte.", conte, ["ecoute", "lis"], 1, "B",
          script="Lire le conte en entier, lentement, avec une voix de conteur : pauses aux points, voix grave pour la tortue, voix tremblante au moment du serpent, chanter quelques notes de berceuse. Relire une deuxième fois en montrant les numéros des paragraphes.", sol="Activité d'écoute et de lecture.")
    b.page(f'<span class="tag-doc">📖 CONTE ILLUSTRÉ</span>{e}<div class="c" style="font-size:30pt;margin-top:2mm">🏜️ 🐢 🐺 🐍 🥁 🌧️</div>', "Lire un conte")
    e = E("Je réponds par une phrase complète.", f'<p>1. Qui est le héros ? Comment est-il ? {blank("xl")}</p><p>2. Quel est le problème du village ? {blank("xl")}</p><p>3. Pourquoi la tortue aide-t-elle Nala ? {blank("xl")}</p><p>4. Quels obstacles Nala rencontre-t-elle ? (3) {blank("xl")}</p><p>5. Comment passe-t-elle devant le serpent ? {blank("xl")}</p><p>6. Que se passe-t-il à la fin ? {blank("xl")}</p>', ["lis", "ecris"], 1, "B",
          sol="1. Nala, une orpheline pauvre mais généreuse. — 2. Il ne pleut pas : les puits sont vides, les champs jaunes, les enfants ont soif. — 3. Parce que Nala lui a donné ses dernières gouttes d'eau : elle a un bon cœur. — 4. Le désert brûlant, une hyène affamée, un serpent géant. — 5. Elle chante une berceuse et le serpent s'endort. — 6. Elle frappe le tambour : la pluie tombe ; depuis, les puits ne sont plus vides.")
    e2 = E("Je remets les images de l'histoire dans l'ordre (1 à 6).", '<div class="grid6">' + "".join(f'<div class="card c" style="padding:1.5mm"><span style="font-size:20pt">{a}</span><br><span class="xs">{t}</span><br><b>___</b></div>' for a, t in [("🐍", "le serpent s'endort"), ("🏜️", "la sécheresse"), ("🌧️", "la pluie tombe"), ("🐢", "la tortue parle"), ("🐺", "la hyène"), ("🥁", "le tambour trouvé")]) + '</div>', ["numerote"], 1, "B",
           sol="🐍 4 · 🏜️ 1 · 🌧️ 6 · 🐢 2 · 🐺 3 · 🥁 5")
    e3 = E("Je cherche dans le texte.", '<p>1. Un mot qui veut dire « qui a très faim » (§ 4) : ______________ 2. Une chanson pour faire dormir (§ 4) : une ______________ 3. Le bruit du ciel pendant l\'orage (§ 6) : le ______________ 4. « Tout de suite » (§ 5) : ______________</p>', ["lis", "ecris"], 2, "B",
           sol="1. affamée — 2. berceuse — 3. tonnerre — 4. aussitôt")
    e4 = E("Quelle est la morale du conte ? Je coche, puis j'explique avec mes mots.", '<div class="card">☐ Il faut être fort pour gagner. &nbsp; ☐ La générosité et la douceur sont récompensées. &nbsp; ☐ Il ne faut pas parler aux animaux.</div>' + lines(1), ["lis", "coche", "ecris"], 2, "B",
           sol="La générosité et la douceur sont récompensées : Nala aide la tortue et la hyène, et elle endort le serpent avec douceur.")
    b.page(f'{e}{e2}{e3}{e4}', "Lire un conte")

    # ---------- Leçon 1 : imparfait / passé composé ----------
    l1 = lecon("Raconter au passé : imparfait ou passé composé ?", '''<div class="grid2"><div class="card" style="background:#fff"><b>🖼️ L'imparfait = le décor</b><p class="sm" style="margin:1mm 0 0">la description, la situation, les habitudes :<br><i>Il était une fois une orpheline qui <b>vivait</b> au bord du désert. Elle <b>était</b> pauvre. Les puits <b>étaient</b> vides.</i><br>radical de « nous » + -ais, -ais, -ait, -ions, -iez, -aient</p></div>
<div class="card" style="background:#fff"><b>🎬 Le passé composé = les actions</b><p class="sm" style="margin:1mm 0 0">les événements, ce qui arrive une fois, à un moment précis :<br><i>Un matin, Nala <b>a trouvé</b> une tortue. Elle lui <b>a donné</b> de l'eau. Elle <b>est partie</b>.</i><br>avoir / être + participe passé</p></div></div>''' +
                table(["Les mots qui aident", "Imparfait 🖼️", "Passé composé 🎬"], [["", "autrefois, chaque jour, toujours, souvent, d'habitude, pendant que", "un jour, un matin, soudain, tout à coup, alors, une fois, aussitôt"]], ["42mm", "70mm", "70mm"]) +
                '<div class="astuce" style="margin:2mm 0 0">📕 Dans les livres, on trouve souvent le <b>passé simple</b> à la place du passé composé : <i>il trouva, elle partit, ils vécurent</i>. Je le <b>reconnais</b> : c\'est une action, comme le passé composé. (Je l\'étudierai au volume 3.)</div>')
    e = E("Dans le paragraphe ② du conte, je souligne en bleu les verbes à l'imparfait et en rouge les verbes au passé composé.", '<div class="card" style="line-height:1.8">Une année, la pluie n\'est pas venue. Les puits étaient vides, les champs étaient jaunes et les enfants avaient soif. Le chef du village a dit : « Si personne ne trouve d\'eau, nous devrons partir. »</div>', ["souligne"], 1, "B",
          sol="Imparfait (bleu) : étaient, étaient, avaient — Passé composé (rouge) : n'est pas venue, a dit")
    e2 = E("Même travail avec le paragraphe ③.", '<div class="card" style="line-height:1.8">Un matin, Nala a trouvé une vieille tortue sur le chemin. La pauvre bête ne bougeait plus. Nala lui a donné ses dernières gouttes d\'eau. Alors, la tortue a ouvert les yeux et elle a parlé.</div>', ["souligne"], 1, "B",
           sol="Imparfait : ne bougeait plus — Passé composé : a trouvé, a donné, a ouvert, a parlé")
    b.page(f'{l1}{e}{e2}', "Leçon 1")
    e = E("Décor 🖼️ ou action 🎬 ? Je coche.", table(["", "🖼️", "🎬"], [[x, '<span class="chk"></span>', '<span class="chk"></span>'] for x in ["Le roi avait trois filles.", "Un jour, un dragon est arrivé.", "La forêt était sombre et silencieuse.", "Soudain, le loup a sauté sur la table.", "Chaque soir, la reine chantait.", "Le prince a ouvert la porte."]], ["130mm", "25mm", "25mm"]), ["lis", "coche"], 1, "B",
          sol="🖼️ · 🎬 · 🖼️ · 🎬 · 🖼️ · 🎬")
    e2 = E("Je conjugue à l'imparfait ou au passé composé.", '<div class="card" style="line-height:2">Il était une fois un pauvre pêcheur qui (habiter) ______________ près de la mer. Chaque jour, il (pêcher) ______________ du matin au soir. Un matin, il (attraper) ______________ un poisson d\'or. Le poisson (parler) ______________ : « Libère-moi ! » Le pêcheur (avoir) ______________ pitié et il (ouvrir) ______________ ses mains.</div>', ["complete"], 2, "C",
           sol="habitait · pêchait · a attrapé · a parlé · avait · a ouvert")
    e3 = E("Je reconnais le passé simple. J'écris le verbe au passé composé.", '<p>1. Le prince <b>trouva</b> la clé. → ______________ 2. La sorcière <b>partit</b>. → ______________ 3. Ils <b>vécurent</b> heureux. → ______________ 4. Le loup <b>fut</b> très surpris. → ______________</p>', ["lis", "ecris"], 2, "C",
           sol="1. a trouvé — 2. est partie — 3. ont vécu — 4. a été")
    e4 = E("Défi ! Je continue l'histoire en 4 phrases : 2 phrases de décor (imparfait) puis 2 actions (passé composé). « Il était une fois un dragon qui… »", lines(4), ["ecris"], 3, "C",
           sol="Ex. : Il était une fois un dragon qui vivait dans une grotte. Il était vieux et il avait peur des enfants. Un jour, une petite fille est entrée dans la grotte. Elle a offert une pomme au dragon.")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 2 : connecteurs de temps ----------
    l2 = lecon("Les connecteurs de temps", table(["Pour…", "Les connecteurs", "Exemple"], [
        ["commencer", "Il était une fois · Autrefois · Au début · Un jour", "<b>Un jour</b>, Nala a trouvé une tortue."], ["continuer, enchaîner", "D'abord · Ensuite · Puis · Après · Le lendemain · Trois jours plus tard", "<b>D'abord</b>, elle a traversé le désert. <b>Ensuite</b>…"],
        ["une surprise", "Soudain · Tout à coup · À ce moment-là", "<b>Soudain</b>, elle s'est souvenue…"], ["en même temps", "Pendant ce temps · Pendant que · Au même moment", "<b>Pendant ce temps</b>, au village, les enfants avaient soif."],
        ["une conséquence", "Alors · Aussitôt · C'est pourquoi", "<b>Aussitôt</b>, le ciel est devenu noir."], ["finir", "Enfin · Finalement · À la fin · Depuis ce jour", "<b>Finalement</b>, la pluie est tombée."]], ["34mm", "74mm", "74mm"]) +
                '<div class="astuce" style="margin:2mm 0 0">✍️ Après un connecteur en début de phrase, je mets souvent une <b>virgule</b> : « Soudain<b>,</b> le loup est arrivé. » · Je varie : je n\'écris pas « et après… et après… et après » !</div>')
    e = E("Je souligne les connecteurs de temps dans le paragraphe ④ du conte « Le tambour de la pluie ». J'en trouve : ______", '<div class="card sm" style="line-height:1.7">Nala est partie le soir même. Elle a marché pendant trois jours. D\'abord, elle a traversé le désert brûlant. Ensuite, elle a rencontré une hyène affamée… Enfin, elle est arrivée devant la grotte… Soudain, elle s\'est souvenue des paroles de sa grand-mère…</div>', ["souligne"], 1, "B",
          sol="4 (+ « le soir même ») : D'abord · Ensuite · Enfin · Soudain")
    e2 = E("Je relie le connecteur et ce qu'il exprime.", relie(["Il était une fois", "Soudain", "Pendant ce temps", "Aussitôt", "Depuis ce jour"], ["une conséquence immédiate", "la fin, ce qui ne change plus", "le début du conte", "une surprise", "deux actions en même temps"]), ["relie"], 1, "B",
           sol="Il était une fois → début · Soudain → surprise · Pendant ce temps → en même temps · Aussitôt → conséquence immédiate · Depuis ce jour → la fin")
    b.page(f'{l2}{e}{e2}', "Leçon 2")
    e = E("Je complète avec : un jour · d'abord · ensuite · soudain · finalement.", '<div class="card" style="line-height:2">Il était une fois un renard très gourmand. ______________, il a vu un corbeau avec un fromage. ______________, il a fait des compliments au corbeau. ______________, il lui a demandé de chanter. ______________, le corbeau a ouvert son bec et le fromage est tombé ! ______________, le renard est parti avec le fromage.</div>', ["complete"], 1, "C",
          sol="Un jour · D'abord · Ensuite · Soudain · Finalement")
    e2 = E("Je remplace « et après » par des connecteurs variés. Je réécris le texte de Mateo.", '<div class="card sm" style="font-family:monospace;background:#fff">Le prince est entré dans la forêt et après il a vu une cabane et après il a frappé à la porte et après une sorcière a ouvert et après il a eu peur.</div>' + lines(3), ["ecris"], 2, "C",
           sol="Ex. : Le prince est entré dans la forêt. Puis, il a vu une cabane. Il a frappé à la porte. Soudain, une sorcière a ouvert. Alors, il a eu peur.")
    e3 = E("J'écoute le conte de Fatou (Leuk le lièvre). Je numérote les connecteurs dans l'ordre où je les entends.", '<div class="grid3" style="gap:1mm 4mm"><p>___ ensuite</p><p>___ un jour</p><p>___ finalement</p><p>___ soudain</p><p>___ alors</p><p>___ d\'abord</p></div>', ["ecoute", "numerote"], 2, "A",
           script="« Leuk le lièvre était le plus malin des animaux de la savane. Un jour, Bouki l'hyène a voulu voler ses provisions. D'abord, elle a attendu la nuit. Ensuite, elle s'est cachée derrière un arbre. Soudain, Leuk est sorti de sa maison avec un grand sac. Alors, Bouki a sauté sur le sac… mais il était plein d'épines ! Finalement, Bouki s'est enfuie en criant et Leuk a bien ri. » (récit inspiré des contes de Leuk-le-Lièvre)",
           sol="ensuite 3 · un jour 1 · finalement 6 · soudain 4 · alors 5 · d'abord 2")
    e4 = E("Défi ! Je raconte ma journée d'hier comme un conte, avec 5 connecteurs différents.", lines(4), ["ecris"], 3, "C",
           sol="Ex. : Hier matin, je me suis levé tôt. D'abord, j'ai pris mon petit déjeuner. Ensuite, je suis allé à l'école. Soudain, il a commencé à pleuvoir. Finalement, je suis rentré trempé !")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 3 : schéma narratif (FLSco) ----------
    sch = '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:1.5mm;margin-top:2mm">' + "".join(f'<div class="card c" style="padding:2mm;background:{c}"><span style="font-size:18pt">{e}</span><br><b class="sm">{t}</b><p class="xs" style="margin:1mm 0 0">{d}</p></div>' for e, t, d, c in [
        ("🖼️", "1. Situation initiale", "Qui ? Où ? Quand ? Le décor, le calme avant l'histoire (imparfait).", "#FFF7E0"), ("⚡", "2. Élément perturbateur", "Un problème arrive et change tout. (Un jour…)", "#FDE3DB"), ("🧗", "3. Péripéties", "Les aventures, les obstacles du héros. (D'abord… ensuite…)", "#E8F1FB"),
        ("🔑", "4. Élément de résolution", "Ce qui règle le problème. (Soudain… alors…)", "#E6F5EC"), ("🌈", "5. Situation finale", "Le nouveau calme, la fin. (Finalement… depuis ce jour…)", "#F1E9FA")]) + '</div>'
    l3 = lecon("Le schéma narratif", '<p class="sm" style="margin:0">Presque toutes les histoires (contes, romans, films) suivent le même plan en 5 étapes. En classe, en français, on demande souvent de <b>« dégager le schéma narratif »</b> : retrouver les 5 étapes du récit.</p>' + sch +
                '<div class="astuce" style="margin:2mm 0 0">🎒 <b>Les mots de la consigne</b> : <b>dégager</b> = trouver et montrer · <b>le récit</b> = l\'histoire racontée · <b>le narrateur</b> = celui qui raconte · <b>le personnage principal</b> = le héros · <b>un obstacle</b> = une difficulté sur le chemin.</div>')
    e = E("Je dégage le schéma narratif du « Tambour de la pluie ». J'écris le numéro des paragraphes et je résume chaque étape en une phrase.", table(["Étape", "§", "Résumé en une phrase"], [["1. Situation initiale", "", ""], ["2. Élément perturbateur", "", ""], ["3. Péripéties", "", ""], ["4. Élément de résolution", "", ""], ["5. Situation finale", "", ""]], ["50mm", "14mm", "118mm"]).replace("<td></td>", '<td style="height:11mm"></td>'), ["lis", "ecris"], 2, "B",
          sol="1. § ① Nala, orpheline pauvre et généreuse, vit au bord du désert. — 2. § ② La pluie ne vient pas, le village risque de partir. — 3. § ③-④ La tortue l'envoie à la montagne ; elle traverse le désert, rencontre la hyène et le serpent. — 4. § ④-⑤ Elle endort le serpent, trouve le tambour et le frappe. — 5. § ⑥ La pluie revient ; les puits ne sont plus jamais vides.")
    b.page(f'<span class="tag-doc">🎒 FRANÇAIS DE L\'ÉCOLE</span>{l3}{e}', "Consignes & école")
    e = E("Je remets les étapes du conte du corbeau et du renard dans l'ordre du schéma narratif (1 à 5).", '<div class="card" style="line-height:1.9">___ Le renard flatte le corbeau et lui demande de chanter.<br>___ Un corbeau est perché sur un arbre avec un fromage dans son bec.<br>___ Le renard part avec le fromage ; le corbeau a compris la leçon.<br>___ Un renard affamé passe et voit le fromage.<br>___ Le corbeau ouvre le bec pour chanter : le fromage tombe.</div>', ["lis", "numerote"], 1, "B",
          sol="3 · 1 · 5 · 2 · 4")
    e2 = E("Je relie l'étape et la phrase du conte de la moufle.", relie(["situation initiale", "élément perturbateur", "péripéties", "résolution", "situation finale"], ["Un grillon entre à son tour : la moufle éclate !", "Un vieil homme perd sa moufle dans la forêt enneigée.", "Les animaux retournent dans la forêt ; le vieil homme retrouve un morceau de moufle.", "Il fait très froid, un vieil homme marche dans la forêt avec son chien.", "Une souris, une grenouille, un lièvre, un renard, un loup, un ours entrent un par un."]), ["relie"], 2, "B",
           sol="situation initiale → il fait très froid… · perturbateur → il perd sa moufle · péripéties → les animaux entrent un par un · résolution → le grillon entre, la moufle éclate · situation finale → les animaux retournent dans la forêt")
    e3 = E("Dans les autres cours ! Je lis les consignes et je les explique avec mes mots.", '<div class="card sm" style="background:#fff">1. « <b>Dégagez</b> les étapes de l\'expérience. » (sciences) 2. « <b>Résumez</b> le récit en cinq lignes. » 3. « <b>Identifiez</b> le personnage principal. » 4. « Situez l\'événement <b>dans le temps</b>. » (histoire)</div>' + lines(3), ["lis", "ecris"], 2, "B",
           sol="1. Trouvez et écrivez les étapes de l'expérience. 2. Racontez l'essentiel de l'histoire en cinq lignes. 3. Trouvez qui est le héros. 4. Dites quand l'événement s'est passé (date, époque).")
    b.page(f'{e}{e2}{e3}', "Consignes & école")
    e = E("Un film, une série, un conte : je choisis une histoire que je connais bien et je remplis son schéma narratif.", '<p>Titre : ______________________________</p>' + table(["Étape", "Ce qui se passe"], [["🖼️ Situation initiale", ""], ["⚡ Élément perturbateur", ""], ["🧗 Péripéties", ""], ["🔑 Résolution", ""], ["🌈 Situation finale", ""]], ["54mm", "128mm"]).replace("<td></td>", '<td style="height:24mm"></td>'), ["ecris"], 2, "C",
          sol="Schéma complet et cohérent : un problème, des obstacles, une solution, une fin.")
    e2 = E("Je présente mon schéma à un camarade en 1 minute. Il devine le titre !", '', ["parle", "duo"], 1, "A", sol="Présentation orale avec les mots du schéma narratif.")
    b.page(f'{e}{e2}', "Consignes & école")

    # ---------- Leçon 4 : décrire un personnage ----------
    l4 = lecon("Décrire un personnage", table(["Je décris…", "Expressions", "Exemple"], [
        ["le physique", "il / elle est grand(e), maigre, vieux / vieille · il / elle a les yeux…, les cheveux…, une longue barbe", "La sorcière <b>était vieille</b> et <b>avait un nez crochu</b>."], ["le caractère", "il / elle est courageux(se), rusé(e), jaloux(se)…", "Le lièvre <b>était malin</b> mais <b>paresseux</b>."],
        ["les vêtements, les objets", "il / elle porte… · il / elle tient…", "Le roi <b>portait</b> une couronne d'or."], ["avec une comparaison", "fort <b>comme</b> un lion · rapide <b>comme</b> le vent · <b>aussi</b> blanc <b>que</b> la neige", "Ses cheveux étaient <b>noirs comme</b> la nuit."]], ["36mm", "84mm", "62mm"]) +
                '''<div class="grid2 mt2"><div class="card" style="background:#fff"><b>Le féminin des adjectifs</b><p class="sm" style="margin:1mm 0 0">-eux → -euse : courageux → courageuse<br>-if → -ive : naïf → naïve · -er → -ère : fier → fière<br>-en, -on → -enne, -onne : bon → bonne<br>vieux → vieille · beau → belle · doux → douce</p></div>
<div class="card" style="background:#fff"><b>Dans un conte</b><p class="sm" style="margin:1mm 0 0">La description est souvent à l'<b>imparfait</b> (c'est le décor) :<br><i>Il était une fois une princesse qui <b>était</b> très curieuse. Elle <b>avait</b> les cheveux longs et elle <b>portait</b> toujours une robe verte.</i></p></div></div>''')
    e = E("J'écris l'adjectif au féminin.", '<p>1. un roi généreux → une reine ______________ 2. un prince naïf → une princesse ______________ 3. un vieux paysan → une ______________ paysanne 4. un ogre cruel → une ogresse ______________ 5. un bon génie → une ______________ fée 6. un loup jaloux → une louve ______________</p>', ["ecris"], 1, "C",
          sol="1. généreuse — 2. naïve — 3. vieille — 4. cruelle — 5. bonne — 6. jalouse")
    e2 = E("J'invente une comparaison pour chaque personnage (… comme …).", '<p>1. Le dragon était grand comme ______________ . 2. La princesse était belle comme ______________ . 3. Le lièvre courait vite comme ______________ . 4. L\'ogre était méchant comme ______________ .</p>', ["ecris"], 2, "C",
           sol="Ex. : une montagne · une fleur (le jour) · une flèche (le vent) · un loup affamé")
    b.page(f'{l4}{e}{e2}', "Leçon 4")
    e = E("Je complète les comparaisons avec : un lion · le vent · la neige · une souris · le soleil.", '<div class="card" style="line-height:2">1. Le prince était fort comme ______________ . 2. Le cheval courait vite comme ______________ . 3. La princesse avait la peau blanche comme ______________ . 4. Le petit garçon était discret comme ______________ . 5. Ses yeux brillaient comme ______________ .</div>', ["complete"], 1, "C",
          sol="1. un lion — 2. le vent — 3. la neige — 4. une souris — 5. le soleil")
    e2 = E("Je lis la description et je dessine le personnage.", '<div class="grid2"><div class="card sm" style="background:#fff;line-height:1.7">Le géant Bobor était immense, grand comme un arbre. Il avait une barbe rousse et un seul œil au milieu du front. Il portait un chapeau trop petit et des bottes énormes. Il avait l\'air terrible, mais en vérité, il était très gentil et un peu timide.</div><div class="card" style="min-height:44mm"></div></div>', ["lis", "dessine"], 1, "B",
           sol="Dessin : géant, barbe rousse, un œil au milieu du front, petit chapeau, grosses bottes.")
    e3 = E("J'écoute la description du personnage et je trouve qui c'est.", '<div class="grid4">' + "".join(f'<div class="card c"><span style="font-size:22pt">{a}</span><br><b>{t}</b></div>' for a, t in [("🧙‍♀️", "A"), ("🧚", "B"), ("👑", "C"), ("🧑‍🌾", "D")]) + '</div><p class="mt2">C\'est le personnage : ______</p>', ["ecoute", "ecris"], 1, "A",
           script="« Ce personnage était petit et léger. Il avait des ailes transparentes et il tenait une baguette magique. Il était doux et généreux : il aidait toujours les enfants perdus. »", sol="B (la fée)")
    e4 = E("Défi ! Je décris le héros d'un conte de mon pays (physique, caractère, vêtements + une comparaison), à l'imparfait.", lines(4), ["ecris"], 3, "C",
           sol="Description à l'imparfait avec au moins un adjectif de caractère et une comparaison.")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 5 : la quatrième de couverture ----------
    q4 = f'''<div class="doc" style="transform:none;display:grid;grid-template-columns:62mm 1fr;border:1.5px solid #9aa1b1;background:#fff">
<div style="background:{MC};color:#fff;padding:4mm;text-align:center"><div style="font-size:9pt;letter-spacing:2px">COLLECTION « CONTES DU MONDE »</div><div style="font-size:42pt;margin:5mm 0">🦓🌙</div><div style="font-size:15pt;font-weight:800">Le zèbre qui voulait des couleurs</div><div class="sm" style="margin-top:2mm">Contes d'Afrique de l'Est</div><div class="xs" style="margin-top:4mm">① 1<sup>re</sup> de couverture</div></div>
<div style="padding:3mm 4mm;font-size:9.8pt;line-height:1.5"><div class="xs muted">② 4<sup>e</sup> de couverture (le dos du livre) · livre fictif</div>
<p style="margin:1.5mm 0 0"><b>③</b> <b>Pourquoi le zèbre a-t-il des rayures ? Pourquoi la lune suit-elle les voyageurs ?</b></p>
<p style="margin:1mm 0 0"><b>④</b> Dans ce recueil, douze contes de la savane et des montagnes répondent aux grandes questions des enfants. On y rencontre un zèbre jaloux, une girafe trop curieuse et un petit berger plus malin que le lion…</p>
<p style="margin:1mm 0 0"><b>⑤</b> « Des histoires drôles et sages, à lire en famille. » — <i>Le journal des lecteurs (fictif)</i></p>
<p style="margin:1mm 0 0"><b>⑥</b> <b>L'auteure :</b> Sélam Haile (personnage fictif) est née à Addis-Abeba. Elle a écouté ces contes chez sa grand-mère, puis elle les a réécrits en français.</p>
<p style="margin:1mm 0 0"><b>⑦</b> Dès 9 ans · 96 pages · illustrations en couleurs · 12,50 €</p>
<div class="flex" style="justify-content:space-between;margin-top:1.5mm"><span class="xs">⑧ Éditions du Baobab (fictives)</span><span style="font-family:monospace;font-size:8pt;border:1px solid #333;padding:.5mm 2mm">||| ||||| || ||| 0 000000 000000</span></div></div></div>'''
    l5 = lecon("La quatrième de couverture", '''<div class="grid2"><div class="card" style="background:#fff"><b>À quoi sert-elle ?</b><p class="sm" style="margin:1mm 0 0">C'est le <b>dos</b> du livre. Elle donne <b>envie de lire</b>, sans raconter la fin ! On y trouve : ③ une phrase d'accroche (souvent une question) · ④ le résumé du début · ⑤ un avis ou une critique · ⑥ des informations sur l'auteur · ⑦ l'âge, le nombre de pages, le prix · ⑧ l'éditeur et le code-barres.</p></div>
<div class="card" style="background:#fff"><b>📚 Les mots du livre</b><p class="sm" style="margin:1mm 0 0"><b>un recueil</b> : un livre avec plusieurs textes · <b>l'auteur / l'auteure</b> : qui a écrit · <b>l'illustrateur, l'illustratrice</b> : qui a dessiné · <b>l'éditeur</b> : la maison qui fabrique et vend le livre · <b>le titre</b> · <b>la couverture</b> · <b>le résumé</b></p></div></div>''')
    e = E("J'observe la couverture et la 4e de couverture. J'écris le numéro de la partie (③ à ⑧).", q4 + '<div class="grid3 mt2" style="gap:1mm 4mm;font-size:10pt"><p>___ « Des histoires drôles et sages »</p><p>___ « Éditions du Baobab »</p><p>___ « Pourquoi le zèbre… ? »</p><p>___ « Dès 9 ans · 12,50 € »</p><p>___ « née à Addis-Abeba »</p><p>___ « douze contes de la savane »</p></div>', ["lis", "numerote"], 1, "B",
          sol="⑤ · ⑧ · ③ · ⑦ · ⑥ · ④")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span>{l5}{e}', "Leçon 5")
    e = E("Je relis la 4e de couverture et je réponds.", f'<p>1. Combien de contes y a-t-il dans ce livre ? D\'où viennent-ils ? {blank("xl")}</p><p>2. Cite deux personnages. {blank("xl")}</p><p>3. Qui a écrit les contes ? Où les a-t-elle entendus ? {blank("xl")}</p><p>4. Pourquoi la 4e de couverture pose-t-elle des questions ? {blank("xl")}</p><p>5. As-tu envie de lire ce livre ? Pourquoi ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Douze contes d'Afrique de l'Est (de la savane et des montagnes). — 2. Un zèbre jaloux, une girafe curieuse, un petit berger malin (un lion). — 3. Sélam Haile ; chez sa grand-mère. — 4. Pour donner envie de lire et de trouver les réponses dans le livre. — 5. Réponse personnelle justifiée.")
    e2 = E("Je relie le mot du livre et sa définition.", relie(["un recueil", "l'auteure", "l'illustrateur", "l'éditeur", "la phrase d'accroche"], ["la maison qui fabrique et vend le livre", "la personne qui a dessiné les images", "la phrase qui donne envie de lire", "un livre avec plusieurs textes", "la personne qui a écrit le livre"]), ["relie"], 1, "B",
           sol="recueil → plusieurs textes · auteure → a écrit · illustrateur → a dessiné · éditeur → fabrique et vend · accroche → donne envie")
    e3 = E("J'écris la 4e de couverture du « Tambour de la pluie » : une question d'accroche + le résumé du début (sans la fin !) + l'âge des lecteurs.", lines(4), ["ecris"], 3, "C",
           sol="Ex. : Comment une petite orpheline peut-elle sauver tout un village ? Au bord du désert, la pluie ne tombe plus. Une vieille tortue envoie Nala vers la montagne rouge… Mais le chemin est plein de dangers ! Dès 8 ans.")
    e4 = E("Je présente à la classe un livre que j'aime (titre, auteur, de quoi ça parle, mon avis), en 4 phrases. Je ne raconte pas la fin !", lines(4), ["ecris", "parle"], 2, "C",
           sol="Présentation avec les mots du livre (titre, auteur, recueil, résumé) et un avis justifié.")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Document : une légende de Belgique ----------
    leg = f'''<div class="doc" style="transform:none;border:2px solid #3E5C76;background:#fff;padding:3mm 5mm;font-size:10.4pt;line-height:1.55"><div class="flex" style="justify-content:space-between"><b style="font-size:13pt;color:#3E5C76">🐴 Une légende de Wallonie : le cheval Bayard</b><span class="xs muted">texte adapté pour la classe</span></div>
<p style="margin:2mm 0 0">Il y a très longtemps, à l'époque de l'empereur Charlemagne, vivaient quatre frères, les quatre fils Aymon. Ils avaient un cheval extraordinaire : Bayard. Ce cheval était magique. Il comprenait la parole des hommes et il pouvait porter les quatre frères en même temps sur son dos !</p>
<p style="margin:1.5mm 0 0">Un jour, les frères se sont disputés avec Charlemagne. L'empereur, furieux, voulait les punir. Les quatre frères ont fui sur le dos de Bayard à travers les forêts de l'Ardenne. Près de Dinant, au bord de la Meuse, ils se sont retrouvés bloqués devant un énorme rocher. Alors, Bayard a frappé la pierre de son sabot et, d'un saut immense, il a franchi la falaise. Les frères étaient sauvés !</p>
<p style="margin:1.5mm 0 0">Aujourd'hui encore, à Dinant, on peut voir le « rocher Bayard », une haute aiguille de pierre au bord de la route. Selon la légende, la trace du sabot du cheval est toujours visible…</p></div>'''
    e = E("Je lis la légende. Je réponds.", leg + f'<p class="mt2">1. Qui sont les personnages ? {blank("xl")}</p><p>2. Qu\'est-ce que Bayard a de magique ? (2 choses) {blank("xl")}</p><p>3. Pourquoi les frères ont-ils fui ? {blank("xl")}</p><p>4. Qu\'est-ce qu\'on peut voir aujourd\'hui à Dinant ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Les quatre fils Aymon, le cheval Bayard, l'empereur Charlemagne. — 2. Il comprend la parole des hommes ; il peut porter les quatre frères en même temps (il fait un saut immense). — 3. Parce qu'ils s'étaient disputés avec Charlemagne, qui voulait les punir. — 4. Le rocher Bayard, une haute aiguille de pierre au bord de la Meuse (avec, selon la légende, la trace du sabot).")
    e2 = E("Conte ou légende ? Je lis l'encadré et je coche.", '<div class="card sm" style="background:#EEF3F8">Un <b>conte</b> se passe dans un lieu et un temps imaginaires (« il était une fois, dans un pays lointain »). Une <b>légende</b> part d\'un lieu réel ou d\'un personnage historique (Dinant, Charlemagne) et ajoute du merveilleux pour expliquer quelque chose.</div>' +
           table(["", "Conte", "Légende"], [[x, '<span class="chk"></span>', '<span class="chk"></span>'] for x in ["Le cheval Bayard", "Le tambour de la pluie", "Une histoire qui explique le nom d'une vraie montagne"]], ["130mm", "25mm", "25mm"]), ["lis", "coche"], 1, "B",
           sol="Légende · Conte · Légende")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Une légende de Belgique</h2>{e}{e2}', "Document de la vie")
    e = E("Les géants de Belgique. J'écoute le reportage et je complète.", '<div class="card" style="line-height:2.1">Dans beaucoup de villes de Wallonie, des ______________ en osier dansent dans les rues pendant la ______________ . À Ath, le géant le plus célèbre s\'appelle ______________ ; il se marie chaque année avec ______________ . Ces fêtes de géants sont inscrites au patrimoine culturel immatériel de l\'______________ .</div>', ["ecoute", "complete"], 2, "A",
          script="« Bonjour à tous ! Je suis à Ath, dans le Hainaut, pour la ducasse. Ici, chaque année au mois d'août, des géants en osier, hauts de plusieurs mètres, dansent dans les rues. Le plus célèbre s'appelle Goliath : il se marie chaque année avec madame Goliath, la veille de la grande procession ! Ces fêtes de géants de Belgique et du nord de la France sont inscrites au patrimoine culturel immatériel de l'UNESCO. »",
          sol="géants · ducasse · Goliath · madame Goliath · UNESCO")
    e2 = E("Je présente une légende ou une fête de ma ville ou de mon pays (3 phrases : où ? quoi ? pourquoi ?).", lines(4), ["ecris"], 2, "C", sol="Présentation en 3 phrases avec un lieu réel.")
    e3 = E("Je compare : dans mon pays aussi, y a-t-il des géants, des marionnettes, des fêtes avec des personnages de contes ? J'en parle en groupe et j'écris une idée entendue.", lines(2), ["parle", "groupe", "ecris"], 1, "A", sol="Échange interculturel ; une idée notée.")
    e4 = E("Vrai ou faux ? Je réécoute le reportage et je coche.", vf(["Les géants sont en plastique.", "La ducasse d'Ath a lieu au mois d'août.", "Goliath se marie chaque année.", "Il y a des géants seulement en Belgique."]), ["ecoute", "coche"], 1, "A",
           sol="Faux (en osier) · Vrai · Vrai · Faux (aussi dans le nord de la France)")
    b.page(f'{e}{e4}{e2}{e3}', "Document de la vie")

    # ---------- Sons ----------
    e = E("Les sons [ʁ] et [l]. J'écoute et je répète.", '<div class="grid2"><div class="card c"><div class="huge">[ʁ] roi</div><p>au fond de la gorge, comme un petit ronflement 😴<br>le <b>r</b>oi · la sorciè<b>r</b>e · la fo<b>r</b>êt · le d<b>r</b>agon · le t<b>r</b>ésor</p></div><div class="card c"><div class="huge">[l] loup</div><p>la langue touche le haut des dents 👅<br>le <b>l</b>oup · le <b>l</b>ièvre · la <b>l</b>égende · la ba<b>l</b>eine · ma<b>l</b>in</p></div></div>', ["ecoute", "repete"], 1, "A",
          script="Faire sentir : [ʁ] au fond de la gorge (gargarisme léger), la pointe de la langue reste en bas ; [l] la pointe de la langue touche les alvéoles. Paires : roi / loi ; rire / lire ; rang / lent ; la reine / la laine.", sol="Activité orale.")
    e2 = E("J'écoute : [ʁ] ou [l] ? Je coche.", checks(8, ["[ʁ] roi", "[l] loup"]), ["ecoute", "coche"], 2, "A", script="1. la loi — 2. le roi — 3. lire — 4. rire — 5. la laine — 6. la reine — 7. le long — 8. le rond",
           sol="1. [l] — 2. [ʁ] — 3. [l] — 4. [ʁ] — 5. [l] — 6. [ʁ] — 7. [l] — 8. [ʁ]")
    e3 = E("Je lis vite et bien (virelangue).", '<div class="card big c" style="line-height:1.8">Le roi rusé rit, le loup lent lit,<br>la reine range la laine rouge et la longue lettre.</div>', ["lis", "parle"], 2, "B", sol="Lecture à voix haute.")
    e4 = E("J'écris r ou l.", '<div class="card big" style="line-height:2">le d___agon · la ___égende · la p___incesse · le t___ésor · la ba___eine · ma___in · la fo___êt · le ___ièvre</div>', ["complete"], 1, "C", sol="dragon · légende · princesse · trésor · baleine · malin · forêt · lièvre")
    e5 = E("J'écoute et j'entoure le mot que j'entends.", '<div class="card big" style="line-height:2">1. (roi / loi) · 2. (rire / lire) · 3. (rang / lent) · 4. (la reine / la laine) · 5. (rond / long) · 6. (prière / pliure)</div>', ["ecoute", "entoure"], 2, "A",
           script="1. la loi — 2. rire — 3. lent — 4. la reine — 5. rond — 6. pliure", sol="1. loi — 2. rire — 3. lent — 4. la reine — 5. rond — 6. pliure")
    b.page(f'<h2>J\'écoute bien · [ʁ] et [l]</h2>{e}{e2}{e5}{e3}{e4}', "Sons")
    e = E("Raconter avec la voix. J'écoute la prof : la même phrase dite de 4 façons. Je relie.", relie(["voix grave et lente", "voix tremblante, chuchotée", "voix rapide et forte", "voix douce, qui chante"], ["la peur : le serpent garde la grotte…", "le géant qui parle", "la berceuse de Nala", "la course, le danger : vite, vite !"]), ["ecoute", "relie"], 1, "A",
          script="Dire « Qui est là ? » : 1. voix grave et lente (le géant) ; 2. chuchotée, tremblante (la peur) ; 3. rapide et forte (le danger) ; 4. douce et chantante (la berceuse). Faire répéter chaque voix.", sol="grave → le géant · tremblante → la peur · rapide → la course · douce → la berceuse")
    e2 = E("Je prépare la lecture à voix haute du paragraphe ④ : je marque les pauses ( / courte · // longue ) et je souligne les mots à dire plus fort.", '<div class="card" style="line-height:1.9">Enfin, elle est arrivée devant la grotte, mais un serpent géant gardait l\'entrée. Nala tremblait. Soudain, elle s\'est souvenue des paroles de sa grand-mère : « La douceur ouvre toutes les portes. » Elle a chanté une berceuse. Le serpent s\'est endormi.</div>', ["lis", "souligne"], 2, "B",
           sol="Ex. : Enfin, / elle est arrivée devant la grotte, / mais un serpent GÉANT gardait l'entrée. // Nala tremblait. // SOUDAIN, / elle s'est souvenue… : / « La douceur ouvre toutes les portes. » // Elle a chanté une berceuse. // Le serpent s'est endormi.")
    e3 = E("En duo : je lis le paragraphe à mon voisin avec les pauses et les voix. Il coche.", table(["Mon voisin…", "😀", "🙂", "😕"], [[x, '<span class="chk"></span>', '<span class="chk"></span>', '<span class="chk"></span>'] for x in ["fait les pauses aux points et aux virgules", "change de voix (peur, surprise, douceur)", "regarde parfois son public", "prononce bien les [ʁ] et les [l]"]], ["128mm", "18mm", "18mm", "18mm"]), ["parle", "duo", "coche"], 2, "A", sol="Évaluation entre pairs.")
    e4 = E("Je dis chaque réplique avec la bonne voix, puis mon voisin devine le personnage.", '<div class="card" style="line-height:2">🐢 « Tu as un bon cœur. Va jusqu\'à la montagne rouge. »<br>🐍 « Ssss… Qui ose entrer dans ma grotte ? »<br>👨‍🦳 « Si personne ne trouve d\'eau, nous devrons partir. »<br>👧 « Dors, serpent, dors… la nuit est douce… »</div>', ["parle", "duo"], 1, "A",
           sol="Tortue : voix lente et grave · serpent : voix sifflante et menaçante · chef : voix triste et sérieuse · Nala : voix douce, chantée.")
    b.page(f'<h2>J\'écoute bien · lire un conte à voix haute</h2>{e}{e2}{e4}{e3}', "Sons")

    # ---------- Révision spirale ----------
    e = E("🔁 Module 12 · Le passif reconnu. Qui fait l'action ?", '<p>Le serpent a été endormi par Nala. → ______________ · Le village a été sauvé par la pluie. → ______________</p>', ["lis", "ecris"], 1, "B", sol="Nala · la pluie")
    e2 = E("🔁 Module 11 · Le conditionnel de politesse.", '<p>« Vieille tortue, (pouvoir) ______________ -vous m\'aider ? Je (vouloir) ______________ sauver mon village. »</p>', ["complete"], 1, "C", sol="pourriez · voudrais")
    e3 = E("🔁 Module 10 · La cause et la conséquence.", '<p>La pluie ne tombait plus, ______ les puits étaient vides. La tortue a aidé Nala ______ elle avait un bon cœur.</p>', ["complete"], 1, "C", sol="donc (alors) · parce que (car)")
    e4 = E("🔁 Module 8 · qui, que, où.", '<p>Nala est une orpheline ______ vit au bord du désert. La grotte ______ elle a trouvé le tambour est sombre. Le tambour ______ elle a rapporté est magique.</p>', ["complete"], 1, "C", sol="qui · où · qu'")
    e5 = E("🔁 Module 6 · Le comparatif et le superlatif.", '<p>Le lièvre est ______ malin ______ l\'hyène. C\'est l\'animal le ______ rusé de la savane.</p>', ["complete"], 1, "C", sol="plus · que · plus")
    e6 = E("🔁 Module 4 · Les pronoms COD / COI.", '<p>La tortue ? Nala ______ a donné de l\'eau. Le tambour ? Elle ______ a rapporté au village.</p>', ["complete"], 2, "C", sol="lui · l'")
    e7 = E("🔁 Module 3 · Souvenirs d'enfance. Quand j'étais petit(e), qui me racontait des histoires ? Où ? Quand ? (2 phrases à l'imparfait)", lines(2), ["ecris"], 2, "C", sol="Ex. : Quand j'étais petite, ma tante me racontait des contes. Elle les racontait le soir, sur la terrasse.")
    b.page(f'<h2>🔁 Je révise les modules 1 à 12</h2>{e}{e2}{e3}{e4}{e5}{e6}{e7}', "Je révise")

    # ---------- Ateliers ----------
    e = E("L'histoire en chaîne (groupe de 4). Le premier dit : « Il était une fois… ». Chacun ajoute une phrase avec un connecteur (un jour, soudain, alors…). Il faut utiliser les 3 cartes tirées au hasard !", '<div class="grid4" style="gap:2mm">' + "".join(f'<div class="card c" style="background:{TINT}"><span style="font-size:18pt">{a}</span><br><span class="xs">{t}</span></div>' for a, t in [("🐉", "un dragon timide"), ("🗝️", "une clé d'or"), ("🏝️", "une île"), ("🧒", "un orphelin"), ("🪞", "un miroir"), ("🌋", "un volcan"), ("🦊", "un renard"), ("🎻", "un violon magique")]) + '</div>' +
          '<p class="sm mt2">Les phrases de notre histoire :</p>' + lines(6), ["parle", "groupe", "ecris"], 2, "A",
          sol="Évaluer : connecteurs variés, passé (imparfait / passé composé), cohérence, les 3 objets utilisés.")
    e2 = E("Je m'évalue.", table(["", "😀", "🙂", "😕"], [[x, '<span class="chk"></span>', '<span class="chk"></span>', '<span class="chk"></span>'] for x in ["J'ai utilisé un connecteur de temps.", "J'ai parlé au passé.", "J'ai écouté les autres pour continuer l'histoire."]], ["128mm", "18mm", "18mm", "18mm"]), ["coche"], 1, "A", sol="Auto-évaluation.")
    b.page(f'{atl_head("A", "Atelier · L\'histoire en chaîne")}{e}{e2}', "Atelier")
    fab = '<div class="card" style="background:#fff;font-size:10.4pt;line-height:1.6"><b>La cigale et la fourmi</b> <span class="xs muted">(d\'après une fable connue, réécrite pour la classe)</span><br>Tout l\'été, la cigale chantait au soleil. Pendant ce temps, la fourmi travaillait : elle ramassait des graines pour l\'hiver. Quand le froid est arrivé, la cigale n\'avait plus rien à manger. Elle est allée chez la fourmi et elle lui a demandé un peu de nourriture. La fourmi a répondu : « Que faisais-tu cet été ? — Je chantais ! — Tu chantais ? Eh bien, danse maintenant ! »</div>'
    e = E("Je lis la fable. Je réponds.", fab + f'<p class="mt2">1. Que faisait la cigale pendant l\'été ? Et la fourmi ? {blank("xl")}</p><p>2. Quel est l\'élément perturbateur ? {blank("xl")}</p><p>3. La fourmi est-elle généreuse ? Justifie. {blank("xl")}</p><p>4. Quelle est la morale ? Es-tu d\'accord ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. La cigale chantait ; la fourmi travaillait, elle ramassait des graines. — 2. L'arrivée du froid (l'hiver) : la cigale n'a plus rien à manger. — 3. Non : elle refuse d'aider la cigale et se moque d'elle (« danse maintenant ! »). — 4. Il faut prévoir, travailler avant d'avoir besoin ; avis personnel (on peut aussi critiquer le manque de générosité de la fourmi).")
    e2 = E("Une fable, c'est quoi ? Je complète avec : animaux · morale · courte.", '<div class="card">Une fable est une histoire ______________ . Les personnages sont souvent des ______________ qui parlent. À la fin, il y a une ______________ .</div>', ["complete"], 1, "C", sol="courte · animaux · morale")
    e3 = E("Je relève 2 verbes à l'imparfait et 2 verbes au passé composé dans la fable.", lines(1), ["lis", "ecris"], 1, "B", sol="Imparfait : chantait, travaillait, ramassait, n'avait, faisais, chantais — Passé composé : est arrivé, est allée, a demandé, a répondu")
    b.page(f'{atl_head("B", "Atelier · Une fable")}{e}{e2}{e3}', "Atelier")
    e = E("J'invente un petit conte (8 à 10 phrases) avec la roue des contes : je choisis un héros, un lieu, un problème et un objet magique. Je suis le schéma narratif et j'utilise 4 connecteurs.", table(["Héros", "Lieu", "Problème", "Objet magique"], [["une petite pêcheuse", "une île", "un monstre vole le soleil", "un filet d'argent"], ["un berger timide", "une montagne", "la source est gelée", "une flûte"], ["une reine âgée", "un désert", "un sortilège : tout le monde oublie", "un miroir"]], ["46mm", "40mm", "56mm", "40mm"]) + lines(15), ["ecris"], 2, "C",
          sol="Conte complet : 5 étapes du schéma narratif, imparfait (décor) et passé composé (actions), 4 connecteurs variés, formule d'ouverture et de fin.")
    b.page(f'{atl_head("C", "Atelier · J\'invente un conte")}{e}', "Atelier")
    cards = [("🖼️", "Il était une fois un petit chat qui vivait chez un meunier pauvre."), ("⚡", "Un jour, le meunier est mort et le chat a dû partir."), ("🧗", "D'abord, le chat a demandé des bottes. Ensuite, il a apporté des cadeaux au roi."), ("🔑", "Grâce à sa ruse, il a battu l'ogre et pris son château."), ("🌈", "Finalement, son maître a épousé la princesse."),
             ("🖼️", "Autrefois, une petite fille vivait avec sa mère près de la forêt."), ("⚡", "Un jour, sa mère l'a envoyée porter une galette à sa grand-mère."), ("🧗", "Dans la forêt, elle a rencontré le loup, qui est arrivé avant elle chez la grand-mère."), ("🔑", "Un chasseur a entendu des cris et il est entré dans la maison."), ("🌈", "Le chasseur a sauvé la petite fille et la grand-mère.")]
    grid = '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:1.5mm">' + "".join(f'<div class="card c" style="min-height:78mm;padding:2mm;background:{TINT if i < 5 else "#fff"};display:flex;flex-direction:column;justify-content:center"><span style="font-size:20pt">{a}</span><span class="sm">{t}</span></div>' for i, (a, t) in enumerate(cards)) + '</div>'
    e = E("Le jeu des contes mélangés (2 à 4 joueurs). On découpe les 10 cartes et on les mélange, faces cachées. Chacun pioche à son tour. Le premier qui reconstitue les 5 étapes d'un conte (dans l'ordre du schéma narratif) et qui le raconte au passé gagne !", grid, ["joue", "groupe"], 2, "D",
          sol="Conte 1 (Le Chat botté, d'après Perrault) et conte 2 (Le Petit Chaperon rouge, version des frères Grimm avec le chasseur) : situation initiale 🖼️ → perturbateur ⚡ → péripéties 🧗 → résolution 🔑 → situation finale 🌈.")
    e2 = E("Je donne le titre des deux contes du jeu. Je les connais dans ma langue ? Comment s'appellent-ils ?", lines(2), ["ecris"], 1, "C", sol="Le Chat botté · Le Petit Chaperon rouge ; titres dans les langues de la classe.")
    b.page(f'{atl_head("D", "Atelier · Les contes mélangés")}{e}{e2}', "Atelier")

    # ---------- ★ Coup de pouce ----------
    e = E("Je relie le personnage et l'image.", relie(["le roi", "la fée", "le dragon", "le loup", "la sorcière"], ["🐺", "🧙‍♀️", "👑", "🐉", "🧚"]), ["relie"], 1, "B", alpha=True, sol="roi → 👑 · fée → 🧚 · dragon → 🐉 · loup → 🐺 · sorcière → 🧙‍♀️")
    e2 = E("Je complète le début du conte.", '<div class="card" style="background:#F2FBF7"><p class="big" style="line-height:2.2;margin:0">Il ______________ une fois une petite fille.<br>Elle habitait dans une ______________ .<br>Elle avait un ______________ magique.</p></div>', ["complete"], 1, "C", alpha=True, sol="était · maison (forêt, cabane…) · objet au choix (tambour, anneau…)")
    e3 = E("J'entoure le lieu.", '<div class="card big" style="line-height:2.1">Le roi habite dans un (château / puits).<br>Le loup vit dans la (forêt / mer).<br>Le dragon dort dans une (grotte / école).</div>', ["entoure"], 1, "B", alpha=True, sol="château · forêt · grotte")
    e4 = E("Je dessine mon personnage de conte préféré et j'écris son nom.", '<div class="card" style="min-height:40mm;background:#fff"></div><p class="big">C\'est ______________ .</p>', ["dessine", "ecris"], 1, "C", alpha=True, sol="Dessin + nom.")
    b.page(CP.format(t="Les personnages · les lieux") + e + e2 + e3 + e4, "★ Coup de pouce")
    e = E("Je remets l'histoire dans l'ordre (1 à 4).", '<div class="card big" style="line-height:2">___ Un jour, Nala a trouvé une tortue.<br>___ Finalement, la pluie est tombée.<br>___ Il était une fois une orpheline, Nala.<br>___ Ensuite, elle a trouvé le tambour.</div>', ["numerote"], 1, "B", alpha=True, sol="2 · 4 · 1 · 3")
    e2 = E("Je complète avec : un jour · soudain · finalement.", '<div class="card" style="background:#F2FBF7"><p class="big" style="line-height:2.2;margin:0">______________, le prince est entré dans la forêt.<br>______________, un loup est arrivé !<br>______________, le prince est rentré au château.</p></div>', ["complete"], 1, "C", alpha=True, sol="Un jour · Soudain · Finalement")
    e3 = E("Décor 🖼️ ou action 🎬 ? Je coche.", table(["", "🖼️", "🎬"], [[x, '<span class="chk"></span>', '<span class="chk"></span>'] for x in ["La forêt était noire.", "Le loup a sauté.", "La reine avait trois enfants."]], ["130mm", "25mm", "25mm"]), ["coche"], 1, "B", alpha=True, sol="🖼️ · 🎬 · 🖼️")
    e4 = E("Je recopie la phrase avec le connecteur « soudain ».", '<div class="card" style="background:#F2FBF7"><p class="big" style="margin:0">Soudain, le dragon est arrivé.</p><p class="line"></p></div>', ["recopie"], 1, "C", alpha=True, sol="Copie correcte, avec la virgule.")
    b.page(CP.format(t="Raconter dans l'ordre") + e + e2 + e3 + e4, "★ Coup de pouce")
    e = E("Je relie l'étape et l'image.", relie(["Au début, tout va bien.", "Un problème arrive.", "Le héros a des aventures.", "Le problème est réglé.", "À la fin, tout va bien."], ["⚡", "🌈", "🖼️", "🔑", "🧗"]), ["relie"], 1, "B", alpha=True, sol="début → 🖼️ · problème → ⚡ · aventures → 🧗 · réglé → 🔑 · fin → 🌈")
